const $=s=>document.getElementById(s);
const state={ready:false,started:false,paused:false,mode:'foot',x:-150,z:-49,y:0,yaw:-.5,speed:0,vy:0,health:100,money:0,wanted:0,escape:0,busted:0,car:null,mission:null,waypoint:null,route:[],camera:0,quality:'medium',sound:false,elapsed:0,distance:0,jobs:0};
const waterRecovery=new WaterRecovery();let terrain;
const clock=new FixedClock();let modelLayer,renderAlpha=1,previousPose=null;const previousActors=new Map();
function visualPose(){if(!previousPose||previousPose.mode!==state.mode||dist(previousPose,state)>10)return state;return {x:THREE.MathUtils.lerp(previousPose.x,state.x,renderAlpha),z:THREE.MathUtils.lerp(previousPose.z,state.z,renderAlpha),y:THREE.MathUtils.lerp(previousPose.y,state.y,renderAlpha)};}
const keys=new Set(),cars=[],people=[],cops=[];let data,world,graph,renderer,scene,camera,sun,player,marker,mapBase,mapCtx,frameTime=0,lastUi=0,toastUntil=0,collisionCooldown=0,followYaw=0,camOrbit=0,camPitch=.38,drag=null,jumpPressed=false,engineAudio=null,frame=0;
const canvas=$('world'),mini=$('minimap'),miniCtx=mini.getContext('2d');
const minBounds={x:-6050,z:-6550,w:13400,h:12900};
function save(){try{localStorage.setItem('padova-game-v1',JSON.stringify({money:state.money,jobs:state.jobs,quality:state.quality}));}catch{}}
try{const s=JSON.parse(localStorage.getItem('padova-game-v1')||'{}');state.money=Number.isFinite(s.money)?Math.max(0,s.money):0;state.jobs=Number.isFinite(s.jobs)?s.jobs:0;state.quality=['low','medium','high'].includes(s.quality)?s.quality:'medium';}catch{}
function toast(t,seconds=3.5){$('toast').textContent=t;$('toast').hidden=false;toastUntil=state.elapsed+seconds;}
function progress(n,text){$('loadingBar').style.width=n+'%';$('loadingText').textContent=text;}
function yieldFrame(){return new Promise(r=>requestAnimationFrame(r));}

function compactCar(group){const positions=[],colors=[],normals=[];group.updateMatrixWorld(true);const inverseRoot=group.matrixWorld.clone().invert();const v=new THREE.Vector3(),n=new THREE.Vector3();const remove=[];group.traverse(o=>{if(!o.isMesh||o.material.transparent)return;const g=o.geometry,ind=g.index?.array,p=g.attributes.position,no=g.attributes.normal,c=o.material.color,nm=new THREE.Matrix3().getNormalMatrix(new THREE.Matrix4().multiplyMatrices(inverseRoot,o.matrixWorld));for(let j=0;j<(ind?.length||p.count);j++){const i=ind?ind[j]:j;v.fromBufferAttribute(p,i).applyMatrix4(o.matrixWorld).applyMatrix4(inverseRoot);n.fromBufferAttribute(no,i).applyMatrix3(nm).normalize();positions.push(v.x,v.y,v.z);normals.push(n.x,n.y,n.z);colors.push(c.r,c.g,c.b);}remove.push(o);});for(const o of remove)o.parent?.remove(o);const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));g.setAttribute('normal',new THREE.Float32BufferAttribute(normals,3));g.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));const mesh=new THREE.Mesh(g,new THREE.MeshStandardMaterial({vertexColors:true,roughness:.65}));mesh.castShadow=true;mesh.receiveShadow=true;group.add(mesh);return group;}
const vehicleStyles=['mito','motorcycle','truck','scooter','sedan','sport','compact','wagon','utility'];
function poseVehicle(c){c.mesh.position.set(c.x,terrain.height(c.x,c.z),c.z);c.mesh.rotation.set(terrain.slope(c.x,c.z,c.yaw,c.spec.wheelbase),c.yaw,0,'YXZ');if(c.rider)c.rider.visible=c===state.car||!c.parked;}
function addCar(x,z,yaw=0,police=false,parked=false,requestedStyle=null){
 const palette=['#a92731','#567e7e','#c87358','#e4dbba','#48677b','#8f9b6f','#9b4e4a','#59606b','#d0d3ce'],index=cars.length,style=police?'sedan':requestedStyle||vehicleStyles[index%vehicleStyles.length],color=police?'#193b54':palette[index%palette.length];
 const m=compactCar(['mito','motorcycle','scooter','truck'].includes(style)?createVehicle(style,color):createCar(color,police,style)),spec=VEHICLES[style];
 const c={x,z,yaw,speed:0,health:100,mesh:m,police,parked,target:null,prev:null,name:police?'Polizia':spec.name,style,spec,path:[],pathIndex:0,routeAt:0,stuck:0};
 if(isBike(style)){c.rider=createRider();m.add(c.rider);}
 poseVehicle(c);scene.add(m);
 if(police){const mat=new THREE.MeshBasicMaterial({color:'#419cff'});const lamp=new THREE.Mesh(new THREE.BoxGeometry(.4,.18,.32),mat);lamp.position.set(-.35,1.84,-.15);m.add(lamp);c.lamp=lamp;c.beacon=new THREE.PointLight('#298aff',0,13,2);c.beacon.position.set(0,2,0);m.add(c.beacon);cops.push(c);}else cars.push(c);return c;
}
function dryRoad(pos,spec=null,ignore=state.car){return safeDryRoad(pos,graph,world.collision,terrain,spec,p=>![...cars,...cops].some(c=>c!==ignore&&c.mesh.visible&&dist(c,p)<(c.spec.length+(spec?.length||1))/2+1));}
function vehiclesMenu(){if(!state.started||waterRecovery.active)return;showMenu('Choose a vehicle','<p class="about-copy">Bring a vehicle to a clear road nearby. E to get in. V opens this menu.</p><div class="activities">'+['mito','motorcycle','scooter','truck'].map(type=>'<button class="activity" data-vehicle="'+type+'"><span><b>'+VEHICLES[type].name+'</b><small>'+Math.round(VEHICLES[type].max*3.6)+' km/h · '+VEHICLES[type].length+' m</small></span></button>').join('')+'</div>');document.querySelectorAll('[data-vehicle]').forEach(button=>button.onclick=()=>{
 const type=button.dataset.vehicle,spec=VEHICLES[type];let p=null;
 for(const offset of [12,24,40,70]){const candidate=dryRoad({x:state.x+Math.sin(state.yaw)*offset,z:state.z+Math.cos(state.yaw)*offset},spec);if(candidate&&dist(candidate,state)>spec.length/2+3&&![...cars,...cops].some(c=>c.mesh.visible&&dist(c,candidate)<(c.spec.length+spec.length)/2+2)){p=candidate;break;}}
 if(!p){toast('No clear space nearby. Move to a wider road.');return;}
 let c=cars.find(c=>c!==state.car&&c.style===type);if(!c)c=addCar(p.x,p.z,p.yaw,false,true,type);c.x=p.x;c.z=p.z;c.yaw=p.yaw;c.speed=0;c.health=100;c.parked=true;c.mesh.visible=true;poseVehicle(c);previousActors.delete(c.mesh);closeDialogs();state.waypoint={x:c.x,z:c.z,name:c.name};routeTo(state.waypoint);toast(c.name+' is waiting '+Math.round(dist(state,c))+' m away. Follow the marker.',5);
 });}
function goodNearbyNode(pos,minD=50,maxD=500,spec=null){const candidates=[];for(const s of graph.index.near(pos.x,pos.z,maxD)){if(!s.connected||s.road.w<(spec?.length>6?7:5)||s.road.k==='pedestrian')continue;for(const id of [s.a,s.b]){const n=graph.nodes[id],d=dist(n,pos);if(d>minD&&d<maxD&&n.edges.length&& !collides(n.x,n.z,spec?spec.width/2:1.3,world.collision)&&terrain.dry(n.x,n.z,spec?spec.length/2:1))candidates.push(id);}}return candidates.length?candidates[Math.floor(Math.random()*candidates.length)]:null;}
function placeTraffic(c,minD=100,maxD=550){const id=goodNearbyNode(state,minD,maxD,c.spec);if(id===null){c.mesh.visible=false;return;}const n=graph.nodes[id];c.x=n.x;c.z=n.z;c.prev=id;c.target=n.edges[Math.floor(Math.random()*n.edges.length)]?.id;c.stuck=0;if(c.target!==undefined){const t=graph.nodes[c.target];c.yaw=Math.atan2(t.x-c.x,t.z-c.z);}const safe=dryRoad(c,c.spec,c);if(!safe||[...cars,...cops].some(other=>other!==c&&other.mesh.visible&&dist(c,other)<(c.spec.length+other.spec.length)/2+2)){c.mesh.visible=false;return;}c.x=safe.x;c.z=safe.z;c.yaw=safe.yaw;c.mesh.visible=true;poseVehicle(c);}
function createPopulation(){const initial=dryRoad(state,VEHICLES.mito);if(initial){state.x=initial.x-3*Math.cos(initial.yaw);state.z=initial.z+3*Math.sin(initial.yaw);if(collides(state.x,state.z,.35,world.collision)||!terrain.dry(state.x,state.z,1)){state.x=initial.x;state.z=initial.z;}state.yaw=initial.yaw;addCar(initial.x,initial.z,initial.yaw,false,true,'mito');state.y=terrain.height(state.x,state.z);waterRecovery.remember(state,terrain);}
 const count=state.quality==='low'?10:state.quality==='high'?28:18;for(let i=0;i<count;i++){const c=addCar(0,0,0,false,i<3);placeTraffic(c,60,520);}
 const population=state.quality==='low'?32:state.quality==='high'?72:48;for(let i=0;i<population;i++){const p={x:0,z:0,yaw:0,seed:i,mesh:createPerson(['#d2b487','#719085','#bc745a','#527789','#c18c77','#6f789b'][i%6],i),at:0};scene.add(p.mesh);people.push(p);placePerson(p);}}
function placePerson(p){const id=goodNearbyNode(state,20,190);if(id===null)return;const n=graph.nodes[id],e=n.edges[0];if(!e)return;const t=graph.nodes[e.id],yaw=Math.atan2(t.x-n.x,t.z-n.z);p.x=n.x+Math.cos(yaw)*3.8;p.z=n.z-Math.sin(yaw)*3.8;p.yaw=yaw;p.at=state.elapsed+8+Math.random()*12;if(collides(p.x,p.z,.35,world.collision)||!terrain.dry(p.x,p.z,.5)){p.x=n.x;p.z=n.z;}}

function makeMap(){mapBase=document.createElement('canvas');mapBase.width=1800;mapBase.height=1740;mapCtx=mapBase.getContext('2d');const c=mapCtx,sx=mapBase.width/minBounds.w,sz=mapBase.height/minBounds.h;c.fillStyle='#1d333c';c.fillRect(0,0,mapBase.width,mapBase.height);const path=(p,close=false)=>{c.beginPath();p.forEach((p,i)=>{const x=(p[0]-minBounds.x)*sx,y=(p[1]-minBounds.z)*sz;if(!i)c.moveTo(x,y);else c.lineTo(x,y);});if(close)c.closePath();};
 for(const a of data.areas){path(a.p,true);c.fillStyle=a.k==='water'?'#33545d':'#284b42';c.fill();}for(const r of data.water){path(r.p);c.strokeStyle='#335d69';c.lineWidth=Math.max(1,r.w*sx);c.stroke();}c.fillStyle='#33474d';for(const b of data.buildings){path(b.p,true);c.fill();}for(const r of data.roads){path(r.p);c.lineWidth=Math.max(.5,r.w*sx);c.strokeStyle=['footway','path','steps'].includes(r.k)?'#405158':'#607278';c.stroke();}
}
function drawRoute(ctx,transform,width=3){if(!state.route.length)return;ctx.beginPath();state.route.forEach((p,i)=>{const a=transform(p);if(!i)ctx.moveTo(a.x,a.y);else ctx.lineTo(a.x,a.y);});ctx.strokeStyle='#edbb65';ctx.lineWidth=width;ctx.lineJoin='round';ctx.lineCap='round';ctx.stroke();}
function drawMini(){if(!mapBase)return;const c=miniCtx,w=mini.width,h=mini.height,range=state.mode==='car'?530:320,k=w/range;c.fillStyle='#172e38';c.fillRect(0,0,w,h);const mx=(state.x-minBounds.x)/minBounds.w*mapBase.width,my=(state.z-minBounds.z)/minBounds.h*mapBase.height,sw=range/minBounds.w*mapBase.width,sh=h/k/minBounds.h*mapBase.height;c.drawImage(mapBase,mx-sw/2,my-sh/2,sw,sh,0,0,w,h);const tr=p=>({x:(p.x-state.x)*k+w/2,y:(p.z-state.z)*k+h/2});drawRoute(c,tr,5);
 for(const p of PLACES){const t=tr(p);if(t.x>5&&t.x<w-5&&t.y>10&&t.y<h-5){c.fillStyle='#c6b28c';c.beginPath();c.arc(t.x,t.y,4,0,Math.PI*2);c.fill();}}
 for(const p of cops){const t=tr(p);c.fillStyle='#76b7ff';c.beginPath();c.arc(t.x,t.y,5,0,Math.PI*2);c.fill();}const target=currentTarget();if(target){const t=tr(target);c.fillStyle='#ffc56a';c.beginPath();c.arc(clamp(t.x,10,w-10),clamp(t.y,10,h-10),7,0,Math.PI*2);c.fill();}
 c.save();c.translate(w/2,h/2);c.rotate(-state.yaw);c.fillStyle='#fff8de';c.strokeStyle='#18323d';c.lineWidth=2;c.beginPath();c.moveTo(0,11);c.lineTo(-7,-7);c.lineTo(0,-3);c.lineTo(7,-7);c.closePath();c.fill();c.stroke();c.restore();c.fillStyle='#bbcbd0';c.font='600 20px system-ui';c.fillText('N',w-28,26);
}
function fullTransform(p){const c=$('fullmap');return {x:(p.x-minBounds.x)/minBounds.w*c.width,y:(p.z-minBounds.z)/minBounds.h*c.height};}
function drawFullMap(){const c=$('fullmap').getContext('2d'),w=$('fullmap').width,h=$('fullmap').height;c.drawImage(mapBase,0,0,w,h);drawRoute(c,fullTransform,3);for(const p of PLACES){const a=fullTransform(p);c.fillStyle='#ffc56a';c.beginPath();c.arc(a.x,a.y,3,0,Math.PI*2);c.fill();}const a=fullTransform(state);c.fillStyle='white';c.strokeStyle='#172e38';c.lineWidth=3;c.beginPath();c.arc(a.x,a.y,8,0,Math.PI*2);c.fill();c.stroke();const target=currentTarget();if(target){const b=fullTransform(target);c.strokeStyle='#ffc56a';c.lineWidth=3;c.beginPath();c.arc(b.x,b.y,10,0,Math.PI*2);c.stroke();c.fillStyle='#ffc56a';c.font='600 19px system-ui';c.fillText('DESTINATION',clamp(b.x+16,5,810),b.y+6);}}
function currentTarget(){return state.mission?.target||state.waypoint;}
function routeTo(target){state.route=target?roadRoute(state,target,graph):[];if(target&&!state.route.length)toast('No connected road route here. Follow the destination marker.');}
function updateMarker(){const t=currentTarget();marker.visible=!!t;if(!t)return;marker.position.set(t.x,terrain.height(t.x,t.z)+.16,t.z);const d=dist(state,t);$('targetDistance').hidden=false;$('targetDistance').textContent=(t.name||'Destination')+' · '+(d>=1000?(d/1000).toFixed(1)+' km':Math.round(d)+' m');}

function toggleVehicle(){if(!state.started||state.paused||waterRecovery.active)return;if(state.mode==='car'){if(Math.abs(state.speed)>7){toast('Slow down before getting out.');return;}const c=state.car;let out=null;for(const a of [Math.PI/2,-Math.PI/2,Math.PI,0]){const p={x:state.x+Math.sin(state.yaw+a)*(Math.abs(Math.sin(a))>.5?c.spec.width/2+1:c.spec.length/2+1),z:state.z+Math.cos(state.yaw+a)*(Math.abs(Math.sin(a))>.5?c.spec.width/2+1:c.spec.length/2+1)};if(!collides(p.x,p.z,.4,world.collision)&&terrain.dry(p.x,p.z,.5)){out=p;break;}}if(!out){toast('No room to get out here.');return;}state.mode='foot';c.parked=true;c.speed=0;c.health=state.health;state.car=null;state.x=out.x;state.z=out.z;state.speed=0;state.y=terrain.height(state.x,state.z);state.vy=0;player.position.set(state.x,state.y,state.z);player.visible=true;toast('On foot. E to get back in.');}else{let nearest=null,d=6;for(const c of cars){const dd=dist(state,c);if(c.mesh.visible&&dd<d&&Math.abs(c.speed)<8){nearest=c;d=dd;}}if(!nearest){toast('Walk closer to a parked or slow-moving car.');return;}state.mode='car';state.y=terrain.height(nearest.x,nearest.z);state.vy=0;state.car=nearest;state.x=nearest.x;state.z=nearest.z;state.yaw=nearest.yaw;state.speed=0;state.health=nearest.health;nearest.parked=true;player.visible=false;toast(nearest.name+' · WASD drive, Space handbrake, Shift boost');}camOrbit=0;followYaw=state.yaw;}
function recover(fromWater=false){
 fromWater=fromWater===true;
 const origin=fromWater?(waterRecovery.lastDry||state):state,p=dryRoad(origin,state.car?.spec)||dryRoad(PLACES[0],state.car?.spec);if(!p){toast('No clear dry road found. Use the map to travel.');return false;}
 previousPose=null;keys.clear();waterRecovery.reset();document.body.classList.remove('water-fall');state.x=p.x;state.z=p.z;state.yaw=p.yaw;state.speed=0;state.y=terrain.height(p.x,p.z);state.vy=0;state.health=100;
 if(state.car){Object.assign(state.car,{x:p.x,z:p.z,yaw:p.yaw,speed:0,health:100});poseVehicle(state.car);previousActors.delete(state.car.mesh);}
 waterRecovery.remember(state,terrain);world.update(state.x,state.z,true);camera.position.set(state.x-10,state.y+9,state.z-12);followYaw=state.yaw;routeTo(currentTarget());toast(fromWater?'Back on dry land. Water cannot be crossed.':'Back on the road. Vehicle repaired.');return true;
}
function falling(dt){
 const done=waterRecovery.step(dt);state.y=waterRecovery.y;
 if(state.car){state.car.mesh.position.y=state.y;state.car.mesh.rotation.x+=dt*.5;}else player.position.set(state.x,state.y,state.z);
 if(done)recover(true);
}
function travel(p){previousPose=null;cancelMission(false);clearPolice();const n=dryRoad(p,state.car?.spec);if(!n)return;waterRecovery.reset();document.body.classList.remove('water-fall');state.x=n.x;state.z=n.z;state.yaw=n.yaw;state.speed=0;state.y=terrain.height(state.x,state.z);state.vy=0;state.health=100;state.waypoint=null;state.route=[];if(state.car){state.car.x=n.x;state.car.z=n.z;state.car.yaw=n.yaw;state.car.speed=0;state.car.health=100;poseVehicle(state.car);previousActors.delete(state.car.mesh);}else{let c=cars.find(c=>c.parked);if(c){const parking=dryRoad({x:n.x+8*Math.sin(n.yaw),z:n.z+8*Math.cos(n.yaw)},c.spec);if(parking){c.x=parking.x;c.z=parking.z;c.yaw=parking.yaw;poseVehicle(c);previousActors.delete(c.mesh);}}}world.update(state.x,state.z,true);for(const c of cars)if(c!==state.car&&!c.parked)placeTraffic(c);people.forEach(placePerson);waterRecovery.remember(state,terrain);camera.position.set(state.x-12,state.y+12,state.z-16);followYaw=state.yaw;toast('Welcome to '+p.name);closeDialogs();}
function ensureCar(){if(state.mode==='car')return true;toast('Get into a car first. A parked car is waiting nearby.');return false;}
const missionTypes={delivery:{title:'Special delivery',desc:'Pick up a parcel, then deliver it across the centre.',reward:'€350'},race:{title:'The Padova run',desc:'Six checkpoints. Five minutes. Your best line.',reward:'€600'},escape:{title:'Lose the tail',desc:'Get the police’s attention, then disappear.',reward:'€500'}};
function safeTarget(p){const n=dryRoad(p);return n?{x:n.x,z:n.z,name:p.name}:p;}
function beginMission(type){if(!ensureCar())return;clearPolice();state.waypoint=null;const now=state.elapsed;if(type==='delivery'){const pickup=safeTarget(PLACES[2]),drop=safeTarget(PLACES[8]);state.mission={type,phase:'pickup',target:pickup,drop,deadline:now+240,title:'A parcel at the piazza',desc:'Reach Piazza delle Erbe and stop in the gold marker to collect the parcel.'};}
 if(type==='race'){const checkpoints=[PLACES[0],PLACES[1],PLACES[2],PLACES[3],PLACES[5],PLACES[8]].map(safeTarget);state.mission={type,phase:'ready',checkpoints,index:0,target:checkpoints[0],deadline:Infinity,title:'Meet at Prato della Valle',desc:'Drive to the start marker. The 5-minute clock starts there.'};}
 if(type==='escape'){state.mission={type,target:null,deadline:now+180,title:'Lose the tail',desc:'Break away from the police. Stay more than 120 m from every patrol for 12 seconds.'};raiseWanted(2);}
 routeTo(currentTarget());closeDialogs();toast(type==='escape'?'The chase is on. Get moving.':'Job accepted. Follow the gold route.');updateMissionUI();}
function cancelMission(notify=true){state.mission=null;state.route=[];if(state.waypoint)routeTo(state.waypoint);if(notify)toast('Activity cancelled.');updateMissionUI();}
function finishMission(reward,message){state.money+=reward;state.jobs++;save();state.mission=null;state.route=[];clearPolice();toast(message+' +€'+reward,6);updateMissionUI();}
function updateMission(dt){const m=state.mission;if(!m)return;if(state.elapsed>m.deadline){toast('Time’s up. Try again from Activities.',5);cancelMission(false);return;}if(m.type==='escape')return;if(!m.target)return;const near=dist(state,m.target)<(m.type==='race'?17:14);if(m.type==='delivery'&&near&&state.mode==='car'&&Math.abs(state.speed)<4){if(m.phase==='pickup'){m.phase='drop';m.target=m.drop;m.title='Take it to Portello';m.desc='The parcel is on board. Deliver it to the gold marker at Portello.';routeTo(m.target);toast('Parcel collected. Next stop: Portello.');}else finishMission(350,'Delivered. Nicely done.');}else if(m.type==='race'&&near&&state.mode==='car'){if(m.phase==='ready'){m.phase='running';m.deadline=state.elapsed+300;m.index=1;m.title='The Padova run';m.desc='Hit every checkpoint before the timer runs out.';toast('GO! First checkpoint: the Santo.');}else{m.index++;toast('Checkpoint '+(m.index-1)+' / 5',1.6);}if(m.index>=m.checkpoints.length){finishMission(600,'Run complete.');return;}m.target=m.checkpoints[m.index];routeTo(m.target);} }
function updateMissionUI(){const m=state.mission;$('missionType').textContent=m?m.type==='race'?'STREET RUN':m.type==='delivery'?'COURIER JOB':'POLICE PURSUIT':'FREE ROAM';$('missionTitle').textContent=m?m.title:'The city is yours.';$('missionDesc').textContent=m?m.desc:'Explore, borrow a car, or pick an activity.';let timer='';if(m&&Number.isFinite(m.deadline)){const s=Math.max(0,Math.ceil(m.deadline-state.elapsed));timer=Math.floor(s/60)+':'+String(s%60).padStart(2,'0');if(m.type==='escape'&&state.escape>0)timer+=' · HIDDEN '+Math.floor(state.escape)+'/12';}else if(m?.type==='race')timer='READY WHEN YOU ARE';$('missionTimer').textContent=timer;}

function clearPolice(){for(const c of cops){scene.remove(c.mesh);previousActors.delete(c.mesh);c.mesh.traverse(o=>{if(o.isMesh&&!o.material.transparent){if(o.geometry!==undefined)o.geometry.dispose();}});}cops.length=0;state.wanted=0;state.escape=0;state.busted=0;}
function raiseWanted(level=1){state.wanted=clamp(Math.max(state.wanted,level),0,5);state.escape=0;while(cops.length<Math.min(4,state.wanted+1)){const id=goodNearbyNode(state,95,200);if(id===null)break;const n=graph.nodes[id];addCar(n.x,n.z,Math.atan2(state.x-n.x,state.z-n.z),true);} }
function updatePolice(dt){if(!state.wanted)return;let nearest=Infinity;for(const c of cops){const d=dist(c,state);nearest=Math.min(nearest,d);if(c.routeAt<state.elapsed){c.path=roadRoute(c,state,graph);c.pathIndex=1;c.routeAt=state.elapsed+1.8+Math.random();}let target=c.path[c.pathIndex];if(target&&dist(c,target)<7){c.pathIndex++;target=c.path[c.pathIndex];}if(d<30||!target)target=state;const goal=Math.atan2(target.x-c.x,target.z-c.z),diff=angleDiff(goal,c.yaw);c.yaw+=clamp(diff,-2.4*dt,2.4*dt);c.speed+=(clamp(d*.45,5,23+state.wanted*2)*(Math.abs(diff)>1?.45:1)-c.speed)*dt*1.5;const nx=c.x+Math.sin(c.yaw)*c.speed*dt,nz=c.z+Math.cos(c.yaw)*c.speed*dt;if(!vehicleBlocked(nx,nz,c.yaw,world.collision,c.spec)&&terrain.dry(nx,nz,c.spec.width/2)){c.x=nx;c.z=nz;c.stuck=0;}else{c.speed*=.5;c.stuck+=dt;if(c.stuck>3){const n=dryRoad(c,c.spec,c);if(n){c.x=n.x;c.z=n.z;}c.stuck=0;c.routeAt=0;}}poseVehicle(c);c.lamp.visible=Math.sin(state.elapsed*16)>0;c.beacon.intensity=c.lamp.visible?8:0;
 if(d<3&&state.mode==='car'&&collisionCooldown<=0){state.speed*=.65;state.health=Math.max(0,state.health-4);collisionCooldown=.5;}if(d>1100){const id=goodNearbyNode(state,250,380);if(id!==null){const n=graph.nodes[id];c.x=n.x;c.z=n.z;}}}
 if(nearest>120){state.escape+=dt;if(state.escape>=12){const reward=state.mission?.type==='escape';clearPolice();if(reward)finishMission(500,'You lost them.');else toast('Escaped. Back to free roam.',5);}}else state.escape=Math.max(0,state.escape-dt*2);
 if(nearest<7&&(state.mode==='foot'||Math.abs(state.speed)<2))state.busted+=dt;else state.busted=Math.max(0,state.busted-dt);if(state.busted>5){const fine=Math.min(150,state.money);state.money-=fine;save();cancelMission(false);clearPolice();recover();toast('Busted. '+(fine?'€'+fine+' fine. ':'')+'Back on the road.',5);}}

function movePlayer(dt){if(waterRecovery.active){falling(dt);return;}const f=(keys.has('KeyW')||keys.has('ArrowUp')?1:0)-(keys.has('KeyS')||keys.has('ArrowDown')?1:0),turn=(keys.has('KeyA')||keys.has('ArrowLeft')?1:0)-(keys.has('KeyD')||keys.has('ArrowRight')?1:0),boost=keys.has('ShiftLeft')||keys.has('ShiftRight');
 if(state.mode==='car'){const car=state.car,spec=car.spec,handbrake=keys.has('Space');if(state.health<=0){state.speed*=Math.exp(-dt*4);if(f)toast('Vehicle disabled. Press R to recover and repair.',1.5);}else{const acceleration=f>0?boost?spec.accel*1.3:spec.accel:f<0?(state.speed>1?-spec.brake:-spec.accel*.65):0;state.speed+=(acceleration+Math.sin(terrain.slope(state.x,state.z,state.yaw,spec.wheelbase))*5)*dt;state.speed*=Math.exp(-dt*(handbrake?2.8:f?.045:.65));state.speed=clamp(state.speed,-spec.reverse,boost?spec.boost:spec.max);const traction=Math.min(1,Math.abs(state.speed)/5);const yaw=state.yaw+turn*(handbrake?spec.steer*1.65:spec.steer)*traction*dt*(state.speed>=0?1:-1);if(!vehicleBlocked(state.x,state.z,yaw,world.collision,spec))state.yaw=yaw;}
 const steps=Math.max(1,Math.ceil(Math.abs(state.speed)*dt/.8)),step=dt/steps;for(let s=0;s<steps;s++){const nx=state.x+Math.sin(state.yaw)*state.speed*step,nz=state.z+Math.cos(state.yaw)*state.speed*step;if(vehicleBlocked(nx,nz,state.yaw,world.collision,spec)){if(collisionCooldown<=0&&Math.abs(state.speed)>4){state.health=Math.max(0,state.health-Math.abs(state.speed)*.85);collisionCooldown=.7;playHit();}state.speed*=-.15;break;}state.x=nx;state.z=nz;if(terrain.waterAt(nx,nz)!==null)break;}
 for(const c of cars){if(c===car)continue;const d=dist(c,state);if(c.mesh.visible&&d<(spec.length+c.spec.length)/2&&vehiclesOverlap({...state,style:car.style},c)&&collisionCooldown<=0){const impact=Math.abs(state.speed-c.speed);state.speed*=-.16;state.health=Math.max(0,state.health-impact*.35);c.speed=0;c.parked=true;collisionCooldown=1;playHit();if(impact>8){raiseWanted(Math.min(3,state.wanted+1));toast('Vehicle collision. Police alerted.');}}}
 car.x=state.x;car.z=state.z;car.yaw=state.yaw;car.health=state.health;state.y=terrain.height(state.x,state.z);poseVehicle(car);car.mesh.rotation.z=-turn*Math.min(isBike(car.style)?.36:.025,Math.abs(state.speed)*(isBike(car.style)?.018:.001));state.distance+=Math.abs(state.speed)*dt;
 }else{
   const view=followYaw+camOrbit, magnitude=Math.hypot(f,turn),speed=magnitude?(boost?7:3.6):0;
   const forward=magnitude?f/magnitude:0,side=magnitude?turn/magnitude:0;
   const dx=(Math.sin(view)*forward+Math.cos(view)*side)*speed*dt;
   const dz=(Math.cos(view)*forward-Math.sin(view)*side)*speed*dt;
   const moved=slideMove(state,dx,dz,.36,world.collision);
   state.speed=Math.hypot(moved.x-state.x,moved.z-state.z)/dt;
   state.x=moved.x;state.z=moved.z;
   if(magnitude)state.yaw+=angleDiff(Math.atan2(dx,dz),state.yaw)*(1-Math.exp(-14*dt));
   if(keys.has('Space')&&!jumpPressed&&state.y<=terrain.height(state.x,state.z)+.08){state.vy=5.7;jumpPressed=true;}
   if(!keys.has('Space'))jumpPressed=false;
   state.vy-=16*dt;const ground=terrain.height(state.x,state.z);state.y=Math.max(ground,state.y+state.vy*dt);if(state.y<=ground+.001)state.vy=0;
   player.position.set(state.x,state.y+.08,state.z);player.rotation.y=state.yaw;
   const swing=state.speed>.1&&state.y<ground+.1?Math.sin(state.elapsed*(boost?13:8))*.55:0;
   player.userData.hips.children[0].rotation.x=swing;player.userData.hips.children[1].rotation.x=-swing;
   player.userData.arms.children[0].rotation.x=-swing*.8;player.userData.arms.children[1].rotation.x=swing*.8;
 }

 const waterY=terrain.waterAt(state.x,state.z);
 if(waterY!==null){if(waterRecovery.enter(Math.max(state.y,terrain.elevation(state.x,state.z)),waterY)){state.y=waterRecovery.y;state.speed=0;keys.clear();document.body.classList.add('water-fall');toast('Water! Returning to dry land…',2);}}else waterRecovery.remember(state,terrain);
 const oldX=state.x,oldZ=state.z;state.x=clamp(state.x,-5970,7250);state.z=clamp(state.z,-6480,6230);if(oldX!==state.x||oldZ!==state.z){state.speed=0;toast('Edge of this map. Turn back towards Padova.',2);}
}
function updateTraffic(dt){for(const c of cars){if(c===state.car)continue;if(!c.mesh.visible){placeTraffic(c);continue;}if(c.parked){poseVehicle(c);continue;}if(dist(c,state)>900)placeTraffic(c);const t=graph.nodes[c.target];if(!t)continue;const d=dist(c,t);if(d<3){const edges=t.edges.filter(e=>e.id!==c.prev),next=(edges.length?edges:t.edges);if(next.length){c.prev=c.target;c.target=next[Math.floor(Math.random()*next.length)].id;}continue;}const yaw=Math.atan2(t.x-c.x,t.z-c.z);c.yaw+=clamp(angleDiff(yaw,c.yaw),-2.5*dt,2.5*dt);const ahead=[...cars,...cops].some(other=>other!==c&&other.mesh.visible&&dist(c,other)<7&&Math.cos(c.yaw)*(other.z-c.z)+Math.sin(c.yaw)*(other.x-c.x)>0);const nearPlayer=dist(c,state)<7||ahead;const desired=nearPlayer?0:Math.abs(angleDiff(yaw,c.yaw))>1?3:Math.min(9,c.spec.max*.35);c.speed+=(desired-c.speed)*dt*2;const nx=c.x+Math.sin(c.yaw)*c.speed*dt,nz=c.z+Math.cos(c.yaw)*c.speed*dt;if(!vehicleBlocked(nx,nz,c.yaw,world.collision,c.spec)&&terrain.dry(nx,nz,c.spec.width/2)){c.x=nx;c.z=nz;c.stuck=0;}else{c.speed=0;c.stuck+=dt;if(c.stuck>4)placeTraffic(c,170,450);}poseVehicle(c);}}
function updatePeople(dt){for(const p of people){if(dist(p,state)>350||p.at<state.elapsed){placePerson(p);}const d=dist(p,state);let speed=1.2;if(state.mode==='car'&&d<8&&Math.abs(state.speed)>4){p.yaw=Math.atan2(p.x-state.x,p.z-state.z);speed=4.5;if(d<1.7&&collisionCooldown<=0){raiseWanted(Math.min(3,state.wanted+1));collisionCooldown=1;toast('Dangerous driving. Police alerted.');}}const nx=p.x+Math.sin(p.yaw)*speed*dt,nz=p.z+Math.cos(p.yaw)*speed*dt;if(!collides(nx,nz,.4,world.collision)&&terrain.dry(nx,nz,.5)){p.x=nx;p.z=nz;}else p.yaw+=Math.PI/2;p.mesh.position.set(p.x,terrain.height(p.x,p.z),p.z);p.mesh.rotation.y=p.yaw;const a=Math.sin(state.elapsed*5+p.seed)*.3;p.mesh.userData.hips.children[0].rotation.x=a;p.mesh.userData.hips.children[1].rotation.x=-a;}}

function updateCamera(dt){
 if(!state.started){const a=state.elapsed*.026;camera.position.set(-170+Math.sin(a)*100,95,-70+Math.cos(a)*100);camera.lookAt(-170,12,-80);return;}
 const speed=Math.abs(state.speed);
 if(state.mode==='car'){
   followYaw+=angleDiff(state.yaw,followYaw)*(1-Math.exp(-4.5*dt));
   if(!drag)camOrbit*=Math.exp(-dt*.45);
 }
 const angle=followYaw+camOrbit;
 let d,h;
 if(state.camera===2){d=30;h=55;}
 else if(state.camera===1){d=state.mode==='car'?4:2.8;h=state.mode==='car'?2.7:2.15;}
 else{d=state.mode==='car'?10+speed*.08:5.8;h=(state.mode==='car'?4.5+speed*.025:2.8)+camPitch*2;}
 if(state.car){d+=Math.max(0,state.car.spec.length-4)*.9;h+=Math.max(0,state.car.spec.height-1.5)*.75;}
 const pose=visualPose(),anchor={x:pose.x,y:pose.y+(state.car?Math.max(1.5,state.car.spec.height*.65):1.5),z:pose.z};
 const desired=cameraBoom(anchor,{x:pose.x-Math.sin(angle)*d,y:pose.y+h,z:pose.z-Math.cos(angle)*d},world.collision);
 const smooth=camera.position.clone().lerp(new THREE.Vector3(desired.x,desired.y,desired.z),1-Math.exp(-dt*10));
 // Re-sweep AFTER smoothing: a safe endpoint alone does not make a safe path.
 const safe=cameraBoom(anchor,smooth,world.collision);
 camera.position.set(safe.x,Math.max(safe.y,terrain.height(safe.x,safe.z)+.5),safe.z);
 camera.lookAt(anchor.x,anchor.y,anchor.z);
 player.visible=state.mode==='foot'&&camera.position.distanceTo(new THREE.Vector3(anchor.x,anchor.y,anchor.z))>.8;
 const targetFov=state.camera===1?68:58+Math.min(9,speed*.18);
 camera.fov=THREE.MathUtils.lerp(camera.fov,targetFov,1-Math.exp(-dt*2));camera.updateProjectionMatrix();
 sun.position.set(state.x-100,state.y+180,state.z+70);sun.target.position.set(state.x,state.y,state.z);sun.target.updateMatrixWorld();
}
function updateUI(){const nearest=PLACES.reduce((a,b)=>dist(a,state)<dist(b,state)?a:b),road=nearestRoad(state,graph);$('location').textContent=dist(nearest,state)<220?nearest.name:road?.segment.road.n||'Padova';$('district').textContent=dist(state,{x:0,z:0})<1700?'CENTRO STORICO':'PADOVA';$('money').textContent=Math.floor(state.money).toLocaleString('en-GB');$('wanted').textContent='★'.repeat(state.wanted)+'☆'.repeat(5-state.wanted);$('wanted').style.opacity=state.escape>0?(Math.sin(state.elapsed*5)>0?.5:1):1;const kmh=Math.round(Math.abs(state.speed)*3.6),health=state.mode==='car'?state.health:100,rpm=state.mode==='car'?clamp(.9+Math.abs(state.speed)*.14+((keys.has('ShiftLeft')||keys.has('ShiftRight'))?1.2:0),.8,7.4):0,compass=['S','SE','E','NE','N','NW','W','SW'];$('speed').textContent=String(kmh).padStart(2,'0');$('vehicleName').textContent=state.mode==='car'?state.car.name.toUpperCase():'ON FOOT';$('gear').textContent=state.mode==='car'?(state.speed<-.4?'R':kmh<2?'N':String(Math.min(6,Math.max(1,Math.ceil(kmh/28))))):'—';$('rpm').style.width=(rpm/7.4*100)+'%';$('rpmValue').textContent=rpm.toFixed(1);$('altitude').textContent=Math.round(terrain.elevation(state.x,state.z))+' M';$('gradient').textContent=state.car?(-Math.tan(terrain.slope(state.x,state.z,state.yaw,state.car.spec.wheelbase))*100).toFixed(1)+'%':'—';$('odometer').textContent=(state.distance/1000).toFixed(1)+' KM';$('heading').textContent=compass[Math.round((((state.yaw%(Math.PI*2))+Math.PI*2)%(Math.PI*2))/(Math.PI/4))%8];const nearbyTraffic=cars.filter(c=>c!==state.car&&dist(c,state)<300).length;$('trafficLevel').textContent=nearbyTraffic>12?'HIGH':nearbyTraffic>6?'MED':'LOW';$('health').style.width=health+'%';$('healthValue').textContent=Math.round(health)+'%';$('healthLabel').textContent=state.mode==='car'?'VEHICLE CONDITION':'SHIFT TO SPRINT';let hint='';if(state.mode==='foot'){const c=cars.find(c=>dist(c,state)<6&&Math.abs(c.speed)<8);if(c&&c.mesh.visible)hint='E · Get in '+c.name;}else if(state.mission?.type==='delivery'&&dist(state,state.mission.target)<25)hint='Stop inside the gold marker';else if(state.health<=0)hint='R · Recover and repair';else if(state.busted>1)hint='MOVE! Police are about to catch you';$('interact').textContent=hint;$('interact').hidden=!hint;if(state.elapsed>toastUntil)$('toast').hidden=true;updateMissionUI();updateMarker();if(!currentTarget())$('targetDistance').hidden=true;drawMini();}

function setPaused(v){state.paused=v;clock.reset();previousPose=null;renderAlpha=1;keys.clear();drag=null;if(v&&engineAudio)engineAudio.gain.gain.setTargetAtTime(0,engineAudio.ctx.currentTime,.1);}
function showMenu(title,content){setPaused(true);$('menuTitle').textContent=title;$('menuContent').innerHTML=content;if(!$('menu').open)$('menu').showModal();}
function closeDialogs(){$('menu').close();$('mapDialog').close();setPaused(false);}
function activities(){if(!state.ready)return;let html='<div class="activities">';for(const [type,m] of Object.entries(missionTypes))html+='<button class="activity" data-mission="'+type+'"><span class="icon">'+({delivery:'◇',race:'⚑',escape:'★'}[type])+'</span><span><b>'+m.title+'</b><small>'+m.desc+'</small></span><span class="reward">'+m.reward+'</span></button>';html+='</div>';if(state.mode!=='car')html+='<p class="about-copy">Get in a car with <kbd>E</kbd> before accepting a job.</p>';if(state.mission)html+='<div class="menu-actions"><button id="cancelJob">Cancel current activity</button></div>';showMenu('A little extra on the side.',html);document.querySelectorAll('[data-mission]').forEach(b=>b.onclick=()=>{if(state.mode!=='car'){closeDialogs();toast('Get in the nearby car with E, then press J.');return;}beginMission(b.dataset.mission);});if($('cancelJob'))$('cancelJob').onclick=()=>{cancelMission();closeDialogs();};}
function pauseMenu(){if(!state.ready)return;showMenu('Take a breather.','<div class="controls-grid"><span><kbd>W / S</kbd> accelerate / reverse</span><span><kbd>A / D</kbd> steer / move sideways</span><span><kbd>E</kbd> enter / leave vehicle</span><span><kbd>V</kbd> choose a vehicle</span><span><kbd>SPACE</kbd> brake / jump</span><span><kbd>SHIFT</kbd> boost / sprint</span><span><kbd>C</kbd> cycle camera</span><span><kbd>M</kbd> city map</span><span><kbd>J</kbd> activities</span><span><kbd>R</kbd> recover & repair</span><span>On foot: WASD follows the camera. Drag to look.</span></div><div class="settings"><label for="quality">Graphics</label><select id="quality"><option value="low">Performance</option><option value="medium">Balanced</option><option value="high">Detailed</option></select><button id="soundBtn" class="textbutton">Sound: '+(state.sound?'on':'off')+'</button></div><p class="about-copy">'+state.jobs+' jobs completed · €'+Math.floor(state.money)+' earned<br>Progress is saved on this browser. Traffic density updates after reloading.<br>Scene: '+renderer.info.render.calls+' draw calls · '+Math.round(renderer.info.render.triangles/1000)+'k triangles.</p><div class="menu-actions"><button class="primary" id="resumeBtn">'+(state.started?'Back to the streets':'Close')+'</button><button id="recoverBtn">Recover vehicle</button><button id="fullscreenBtn">Full screen</button><button id="vehiclesBtn">Choose a vehicle</button><button id="worldInfoBtn">About the world</button></div>');$('quality').value=state.quality;$('quality').onchange=e=>{state.quality=e.target.value;applyQuality();save();};$('resumeBtn').onclick=closeDialogs;$('recoverBtn').onclick=()=>{recover();closeDialogs();};$('fullscreenBtn').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{toast('Use your browser’s full-screen control.');}};$('worldInfoBtn').onclick=about;$('vehiclesBtn').onclick=vehiclesMenu;$('soundBtn').onclick=()=>{state.sound=!state.sound;if(state.sound)initAudio();$('soundBtn').textContent='Sound: '+(state.sound?'on':'off');};}
function about(){const buildings=data?.buildings.length.toLocaleString('en-GB')||'88,000';showMenu('Padova, at street scale.','<div class="about-copy"><p><strong>A playable, stylised reconstruction of Padua.</strong> '+buildings+' mapped building footprints, real streets, waterways and parks across a roughly 13 × 13 km area. One metre in the map is one metre in the game.</p><p>Street geometry and building footprints come from <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap contributors</a> (ODbL). Building heights are estimated where the map has no height data. Facades and landmark details are interpretive. Terrain follows an offline, smoothed elevation grid without exaggeration. Bridge ramps and river levels are approximate. Water causes a fall and automatic recovery; bridges remain usable.</p><p>Elevation: <a href="https://github.com/tilezen/joerd/blob/master/docs/attribution.md" target="_blank" rel="noopener">Mapzen Terrain Tiles · Copernicus EU-DEM · USGS</a>. <a href="./data/terrain.json" download>Download the derived terrain data</a>.</p><p>Buildings with supplied GLB models replace their map extrusions automatically. The remaining city is still approximate; a complete photographic centre is not included.</p><p>This version has outdoor exploration, driving, traffic, courier jobs, checkpoint races and police pursuits. It does not contain photographic buildings, enterable interiors, multiplayer or GTA’s full systems.</p><p>Best on a MacBook with a keyboard. Use <strong>Performance</strong> graphics if movement feels slow. Drag on the scene to look around; no mouse lock needed.</p><p>Built with <a href="https://threejs.org" target="_blank" rel="noopener">Three.js</a> · <a href="./data/padova.json" download>Download the derived map data</a> · <a href="./model-guide.html" target="_blank" rel="noopener">Add real buildings</a></p></div><div class="menu-actions"><button class="primary" id="aboutClose">Back</button></div>');$('aboutClose').onclick=closeDialogs;}
function openMap(){if(!state.ready)return;setPaused(true);$('mapPlaces').innerHTML='<span class="eyebrow">JUMP TO A PLACE</span>'+PLACES.map((p,i)=>'<button data-place="'+i+'">'+p.name+'<small>'+p.tag+'</small></button>').join('')+'<button id="clearWaypoint">Clear waypoint</button>';$('mapPlaces').querySelectorAll('[data-place]').forEach(b=>b.onclick=()=>travel(PLACES[Number(b.dataset.place)]));$('clearWaypoint').onclick=()=>{state.waypoint=null;if(!state.mission)state.route=[];drawFullMap();};drawFullMap();$('mapDialog').showModal();}
$('fullmap').onclick=e=>{const r=$('fullmap').getBoundingClientRect();const size=Math.min(r.width,r.height),offsetX=(r.width-size)/2,offsetY=(r.height-size)/2,px=e.clientX-r.left-offsetX,py=e.clientY-r.top-offsetY;if(px<0||py<0||px>size||py>size)return;if(state.mission){toast('Finish or cancel your activity to set a waypoint.');return;}const p={x:minBounds.x+px/size*minBounds.w,z:minBounds.z+py/size*minBounds.h,name:'Waypoint'};state.waypoint=safeTarget(p);routeTo(state.waypoint);drawFullMap();};
function applyQuality(){world?.setQuality(state.quality);if(renderer){renderer.setPixelRatio(Math.min(devicePixelRatio,state.quality==='low'?1:state.quality==='high'?1.7:1.25));renderer.shadowMap.enabled=state.quality!=='low';renderer.setSize(innerWidth,innerHeight);scene.fog.far=state.quality==='low'?900:state.quality==='high'?1950:1400;camera.far=scene.fog.far+150;camera.updateProjectionMatrix();}}
function initAudio(){if(engineAudio){engineAudio.ctx.resume().catch(()=>{});return;}try{const ctx=new (window.AudioContext||window.webkitAudioContext)(),osc=ctx.createOscillator(),gain=ctx.createGain(),filter=ctx.createBiquadFilter();osc.type='sawtooth';osc.frequency.value=45;filter.type='lowpass';filter.frequency.value=200;gain.gain.value=0;osc.connect(filter).connect(gain).connect(ctx.destination);osc.start();engineAudio={ctx,osc,gain};ctx.resume().catch(()=>{});}catch{state.sound=false;}}
function playHit(){if(!state.sound)return;initAudio();if(!engineAudio)return;const {ctx}=engineAudio,o=ctx.createOscillator(),g=ctx.createGain();o.type='triangle';o.frequency.setValueAtTime(65,ctx.currentTime);o.frequency.exponentialRampToValueAtTime(20,ctx.currentTime+.2);g.gain.setValueAtTime(.17,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.2);o.connect(g).connect(ctx.destination);o.start();o.stop(ctx.currentTime+.22);}

function start(){if(!state.ready)return;state.started=true;state.paused=false;previousPose=null;clock.reset();$('intro').hidden=true;$('playingUI').hidden=false;state.elapsed=0;lastUi=-1;followYaw=state.yaw;camera.position.set(state.x-8,state.y+7,state.z-9);toast('Piazza delle Erbe. WASD to walk, drag to look, E for your MiTo-inspired car, V for motorcycles and trucks.',6);}
$('playBtn').onclick=start;$('pauseBtn').onclick=pauseMenu;$('activityBtn').onclick=activities;$('mapBtn').onclick=openMap;$('closeMenu').onclick=closeDialogs;$('closeMap').onclick=closeDialogs;$('aboutBtn').onclick=about;$('touchCar').onclick=toggleVehicle;$('vehicleMenuBtn').onclick=vehiclesMenu;
for(const d of [$('menu'),$('mapDialog')])d.addEventListener('cancel',()=>setPaused(false));
window.addEventListener('keydown',e=>{if(['KeyW','KeyA','KeyS','KeyD','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code)&&state.started&&!state.paused)e.preventDefault();if(e.repeat)return;if(state.paused){if(e.code==='Escape'){e.preventDefault();closeDialogs();}return;}if(e.code==='Escape'){if(state.started)pauseMenu();return;}if(e.code==='Enter'&&!state.started){start();return;}if(!state.started)return;keys.add(e.code);if(e.code==='KeyE')toggleVehicle();if(e.code==='KeyC'){state.camera=(state.camera+1)%3;toast(['Chase camera','Close camera','Aerial camera'][state.camera],1.5);}if(e.code==='KeyV')vehiclesMenu();if(e.code==='KeyJ')activities();if(e.code==='KeyM')openMap();if(e.code==='KeyR')recover();});
window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>{keys.clear();if(state.started&&!state.paused)pauseMenu();});document.addEventListener('visibilitychange',()=>{if(document.hidden){keys.clear();if(state.started&&!state.paused)pauseMenu();}});
canvas.addEventListener('pointerdown',e=>{if(!state.started||state.paused)return;drag={x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId);});canvas.addEventListener('pointermove',e=>{if(!drag)return;camOrbit-=(e.clientX-drag.x)*.006;camPitch=clamp(camPitch+(e.clientY-drag.y)*.006,-.3,2.5);drag={x:e.clientX,y:e.clientY};});canvas.addEventListener('pointerup',()=>drag=null);canvas.addEventListener('pointercancel',()=>drag=null);canvas.addEventListener('contextmenu',e=>e.preventDefault());
document.querySelectorAll('[data-key]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();keys.add(b.dataset.key);b.setPointerCapture(e.pointerId);});for(const ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,()=>keys.delete(b.dataset.key));});
window.addEventListener('resize',()=>{if(!renderer)return;camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);});

function simulate(dt){
 previousPose={x:state.x,y:state.y,z:state.z,mode:state.mode};
 for(const a of [...cars,...people,...cops])previousActors.set(a.mesh,{x:a.x,z:a.z,y:a.mesh.position.y,yaw:a.yaw});
 state.elapsed+=dt;collisionCooldown=Math.max(0,collisionCooldown-dt);
 if(state.started){movePlayer(dt);updateTraffic(dt);updatePeople(dt);if(!waterRecovery.active){updatePolice(dt);updateMission(dt);}
   if(state.waypoint&&!state.mission&&dist(state,state.waypoint)<15){state.waypoint=null;state.route=[];toast('You’ve reached your waypoint.');}
 }
}
function animate(time){
 requestAnimationFrame(animate);
 const dt=frameTime?Math.min(.15,Math.max(0,(time-frameTime)/1000)):1/60;frameTime=time;
 if(!state.ready)return;frame++;
 if(!state.paused){
   renderAlpha=clock.advance(dt,simulate);
   const pose=visualPose();if(state.mode==='foot')player.position.set(pose.x,pose.y+.08,pose.z);
   for(const a of [...cars,...people,...cops]){const prev=previousActors.get(a.mesh);if(!prev||dist(prev,a)>10)continue;a.mesh.position.x=THREE.MathUtils.lerp(prev.x,a.x,renderAlpha);a.mesh.position.z=THREE.MathUtils.lerp(prev.z,a.z,renderAlpha);a.mesh.position.y=a===state.car&&waterRecovery.active?pose.y:terrain.height(a.mesh.position.x,a.mesh.position.z);a.mesh.rotation.y=prev.yaw+angleDiff(a.yaw,prev.yaw)*renderAlpha;}
   // Chunk creation runs once per render, never inside the catch-up loop.
   world.update(state.started?state.x:-150,state.started?state.z:-49);
   modelLayer?.update(state.x,state.z);
   updateCamera(dt);
   if(marker){marker.children[1].position.y=7+Math.sin(state.elapsed*2)*.7;marker.children[1].rotation.y=state.elapsed*.6;}
   if(state.elapsed-lastUi>.12){updateUI();lastUi=state.elapsed;}
   if(engineAudio){const t=engineAudio.ctx.currentTime;engineAudio.osc.frequency.setTargetAtTime(35+Math.abs(state.speed)*3,t,.1);engineAudio.gain.gain.setTargetAtTime(state.sound&&state.mode==='car'&&!waterRecovery.active?.028:0,t,.15);}
 }
 renderer.render(scene,camera);
}

async function init(){try{progress(5,'Loading the city map…');const [response,terrainResponse]=await Promise.all([fetch('./data/padova.json'),fetch('./data/terrain.json')]);if(!terrainResponse.ok)throw new Error('Terrain download failed');const terrainData=await terrainResponse.json();if(!response.ok)throw new Error('Map download failed ('+response.status+')');const total=Number(response.headers.get('Content-Length'))||18330287;if(response.body){const reader=response.body.getReader(),chunks=[];let size=0;while(true){const {done,value}=await reader.read();if(done)break;chunks.push(value);size+=value.length;progress(Math.min(50,5+size/total*45),'Loading the city map · '+Math.round(size/1024/1024)+' MB');}const all=new Uint8Array(size);let off=0;for(const chunk of chunks){all.set(chunk,off);off+=chunk.length;}data=JSON.parse(new TextDecoder().decode(all));}else data=await response.json();progress(55,'Laying out '+data.buildings.length.toLocaleString('en-GB')+' buildings…');await yieldFrame();
 scene=new THREE.Scene();scene.background=new THREE.Color('#b7c9c6');scene.fog=new THREE.Fog('#b7c9c6',250,1400);camera=new THREE.PerspectiveCamera(60,innerWidth/innerHeight,.12,1600);renderer=new THREE.WebGLRenderer({canvas,antialias:true,powerPreference:'high-performance'});renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.25));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.2;
 scene.add(new THREE.HemisphereLight('#d9e6e6','#766047',2.5));sun=new THREE.DirectionalLight('#ffe0aa',3);sun.position.set(-100,180,800);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-85;sun.shadow.camera.right=85;sun.shadow.camera.top=85;sun.shadow.camera.bottom=-85;sun.shadow.camera.near=1;sun.shadow.camera.far=450;sun.shadow.bias=-.001;sun.shadow.normalBias=.3;scene.add(sun,sun.target);terrain=new Terrain(terrainData,data);world=new CityWorld(scene,data,terrain);modelLayer=new BuildingModels(scene,world);await modelLayer.init();applyQuality();progress(70,'Connecting streets and traffic…');await yieldFrame();graph=makeRoadGraph(data.roads);player=createPerson('#d9bf8f');scene.add(player);createPopulation();world.update(state.x,state.z,true);progress(85,'Drawing your map…');await yieldFrame();makeMap();
 marker=new THREE.Group();const ring=new THREE.Mesh(new THREE.TorusGeometry(11,.27,8,48),new THREE.MeshBasicMaterial({color:'#ffcb72'}));ring.rotation.x=Math.PI/2;const arrow=new THREE.Mesh(new THREE.OctahedronGeometry(1.8),new THREE.MeshStandardMaterial({color:'#ffc56a',emissive:'#8b5d1f',emissiveIntensity:.3}));arrow.position.y=7;marker.add(ring,arrow);const beam=new THREE.Mesh(new THREE.CylinderGeometry(2,10,26,24,1,true),new THREE.MeshBasicMaterial({color:'#ffc56a',transparent:true,opacity:.045,depthWrite:false,side:THREE.DoubleSide}));beam.position.y=13;marker.add(beam);marker.visible=false;scene.add(marker);progress(100,'Ready. '+data.buildings.length.toLocaleString('en-GB')+' buildings · real-world scale');state.ready=true;$('playBtn').disabled=false;$('playBtn').textContent='Enter the city  →';updateUI();requestAnimationFrame(animate);
 }catch(e){console.error(e);progress(100,'');$('loadingText').className='fatal';$('loadingText').textContent='The city could not start. '+(String(e).includes('WebGL')?'Enable WebGL / hardware acceleration in your browser and reload.':'Check your connection and reload to try again.');$('playBtn').textContent='Reload city';$('playBtn').disabled=false;$('playBtn').onclick=()=>location.reload();}}
init();
